// Mapping des IDs de labels Gmail
const labelMap = {
  'Syndic': 'Label_1107215070567604782',
  'Gestion locative': 'Label_1151885618813199628',
  'Factures Carrefour': 'Label_5180827763194058448',
  'Factures Rouen': 'Label_6071725231057128983',
  'Factures Camille': 'Label_8963688369978048774',
  'Receipts': 'Label_4',
  'Blog': 'Label_659885575819992047',
  'ID': 'Label_7',
  'OVH': 'Label_7296642557858161401',
  'Suivi livraison Pichet': 'Label_7692245440759375862',
  'A traiter urgent': 'Label_4938988077910989456',
  'A traiter (non urgent)': 'Label_8411510230508964137',
  'Personal': 'Label_3',
  'Work': 'Label_6'
};

function classifierEmail(from, subject, extrait) {
  const texte = `${from} ${subject} ${extrait}`.toLowerCase();

  // Syndic - copropriété
  if (texte.match(/copropri[ée]t[ée]|syndic|assemblée générale|\bag\b|picaso|asl|manda/i) ||
      from.match(/jeremy.*saurel|saurel.*jeremy/i)) {
    return 'Syndic';
  }

  // Gestion locative
  if (texte.match(/bail|loyer|locataire|location|rouen.*logement|bobigny.*logement|appartement.*rouen|appartement.*bobigny/i)) {
    return 'Gestion locative';
  }

  // Factures Carrefour
  if (texte.match(/carrefour.*facture|carrefour.*achat|carrefour.*ticket/i) || from.includes('carrefour')) {
    return 'Factures Carrefour';
  }

  // Factures Rouen (EDF, eau, gaz)
  if ((texte.match(/edf|enedis|eau|gaz|électricité|facture.*énergie/i)) && 
      (texte.match(/rouen/i) || from.match(/edf|enedis|veolia/i))) {
    return 'Factures Rouen';
  }

  // Blog
  if (texte.match(/camille-patisserie|commentaire.*blog|seo|google.*search|wordpress|adsense/i) || 
      from.includes('patisserie')) {
    return 'Blog';
  }

  // ID - administratif
  if (texte.match(/impôts|caf|urssaf|sécurité sociale|carte.*identité|passeport|préfecture/i) || 
      from.match(/impots\.gouv|caf\.fr|urssaf/i)) {
    return 'ID';
  }

  // OVH
  if (texte.match(/ovh|hébergement|domaine|dns|serveur/i) || from.includes('ovh')) {
    return 'OVH';
  }

  // Suivi livraison Pichet
  if ((texte.match(/livraison|colis|expédition/i)) && texte.match(/pichet/i)) {
    return 'Suivi livraison Pichet';
  }

  // Receipts - reçus
  if (texte.match(/re[çc]u.*paiement|confirmation.*achat|votre.*commande|ticket/i) && 
      !texte.match(/carrefour/i)) {
    return 'Receipts';
  }

  // Urgent
  if (texte.match(/urgent|imm[ée]diat|rapidement|d[ée]lai.*court|avant.*\d+\/\d+|action.*requise/i)) {
    return 'A traiter urgent';
  }

  // Personal
  if (texte.match(/famille|anniversaire|vacances|personnel/i)) {
    return 'Personal';
  }

  // Work (professionnel hors blog)
  if (texte.match(/projet|réunion|client|devis|contrat|professionnel/i)) {
    return 'Work';
  }

  // Autres factures
  if (texte.match(/facture|paiement|montant.*[€]|total.*[€]/i)) {
    return 'Factures Camille';
  }

  // Par défaut - non urgent
  return 'A traiter (non urgent)';
}

// Traiter tous les emails
const results = [];

for (const item of $input.all()) {
  const category = classifierEmail(
    item.json.from || '',
    item.json.subject || '',
    item.json.extrait || ''
  );

  const labelId = labelMap[category];

  // Ne retourner que si un label différent doit être appliqué
  if (labelId && !item.json.labelIds.includes(labelId)) {
    results.push({
      json: {
        message_id: item.json.id,
        label_id: labelId,
        label: category
      }
    });
  }
}

return results;
